    "magpie's sign-in to it is forgotten too.": "magpie 对它的登录也会一并清除。",
    "The skills magpie placed in {n} projects are taken away too.": "magpie 放进 {n} 个项目的这些技能也会一并移除。",
    "{n} folders are moved to magpie's backups (Backups, at the top of the Library), not deleted.": "{n} 个技能文件夹将移到 magpie 的备份（资源库顶部的「备份」），不会删除。",
    "{n} linked from folders of your own are only unlinked: those folders stay where they are.": "{n} 个链接自你文件夹的技能只取消链接，原文件夹保留。",
    "Remove all {n}": "删除全部 {n} 个",
    "{n} skills removed": "已删除 {n} 个技能",
    "{name} wasn't removed: {error}": "{name} 未能删除：{error}",
    "Stop picking servers": "结束多选",
    "Copy config…": "复制配置…",
    "As Claude Code's .mcp.json has it. A value naming a variable, as {ref}, stays a name here": "与 Claude Code 的 .mcp.json 格式相同。像 {ref} 这样引用变量的值，在这里仍然是变量名",
    "This isn't an MCP server's JSON": "这不是 MCP 服务器的 JSON",
    "Only one server here; paste several outside this box to add them": "这里只能写一个服务器；要一次添加多个，请粘贴到这个框外面",
    "Optional: what it's for and when to use it, in any language. Only the library keeps it; no agent is given it": "可选：用任何语言写下它的用途、什么时候用。只保存在资源库里，不会交给任何 Agent",
    "e.g. The shop's database, read only": "例如：店里的数据库，只读",
    "e.g. For the weekly report; the other PDF skill is for forms": "例如：写周报用；另一个 PDF 技能是填表用的",
    "Copy as an agent's project file": "按 agent 的项目配置文件复制",
    "{agent} can't take {names} from a project's file": "{agent} 的项目配置文件放不了 {names}",
    "Copied for {agent}, to paste into {file} in your project. Left out, as {agent} can't take them there: {names}": "已按 {agent} 的格式复制，粘贴到项目里的 {file} 即可。{agent} 在那里放不了、没有复制的：{names}",
    "Copied for {agent}, to paste into {file} in your project": "已按 {agent} 的格式复制，粘贴到项目里的 {file} 即可",
    "Copy {name} as an agent's project file has it, to paste into a project yourself": "按某个 agent 的项目配置文件格式复制 {name}，自己粘贴到项目里",
    "Copy these servers as an agent's project file has them, to paste into a project yourself": "按某个 agent 的项目配置文件格式复制这些服务器，自己粘贴到项目里",
    "Pick some servers and turn them on or off together": "选中多个服务器，一起开启或关闭",
    "Pick servers to turn them on or off together": "勾选服务器，再用右侧图标一起开启或关闭",
    "{agent} can reach none of these servers": "{agent} 无法连接其中任何服务器",
    "{agent} has all of these servers — click to take them away": "{agent} 已有其中全部服务器，点击全部关闭",
    "{agent} has {n} of these servers — click to give it the rest": "{agent} 已有其中 {n} 个服务器，点击补齐其余的",
    "Give {agent} all of these servers": "为 {agent} 启用其中全部服务器",
