    "{agent} has all of these hooks — click to take them away": "{agent} 已有这些 Hook — 点击全部停用",
    "{agent} has hooks turned off in its settings: it runs none of them until they're turned on there.": "{agent} 在自己的设置里关闭了 Hook：在那里重新打开之前，它一个也不会运行。",
    "{agent} has no hooks magpie can write": "magpie 还不能给 {agent} 写入 Hook",
    "{agent}'s own event": "{agent} 自己的事件",
    "{event} is {agent}'s own event: only it can run this hook": "{event} 是 {agent} 自己的事件：只有它能运行这个 Hook",
    "{n} hooks are off for {agents}": "已为 {agents} 停用 {n} 个 Hook",
    "{n} hooks are on for {agents}": "已为 {agents} 启用 {n} 个 Hook",
    "{n} hooks removed": "已删除 {n} 个 Hook",
    "A hook is a command an agent runs at a point of its turn — a notification when it ends, a formatter after it edits a file. Add it once and magpie writes it into each agent you pick, in the shape that agent reads.": "Hook 是 Agent 在一轮对话的某个时刻运行的命令——结束时发个通知，改完文件后跑一下格式化。只需添加一次，magpie 会按每个 Agent 自己读取的格式，写进你选中的 Agent。",
    "Add one, and pick the agents that run it.": "添加一个，再选要运行它的 Agent。",
    "After a tool runs": "工具运行之后",
    "Before a tool runs": "工具运行之前",
    "Codex runs a new or changed hook only once you trust it: review it in Codex's /hooks.": "新加或改过的 Hook，Codex 要等你信任后才会运行：请在 Codex 的 /hooks 里审阅。",
    "Cursor runs Claude Code's hooks too: a hook given to both runs twice in Cursor.": "Cursor 也会运行 Claude Code 的 Hook：同时给两者启用的 Hook，在 Cursor 里会运行两次。",
    "e.g. notify": "例如 notify",
    "Each agent's own names for them": "按每个 Agent 自己对它们的叫法",
    "Every agent has all of these hooks — click to take them from every one": "每个 Agent 都已有这些 Hook — 点击从全部 Agent 停用",
    "File edits": "编辑文件",
    "For which tools": "对哪些工具",
    "Any start": "任何开始",
    "A fresh session": "新会话",
    "A resumed session": "恢复的会话",
    "After /clear": "/clear 之后",
