    "{agent} never starts a session that way": "{agent} 不会以这种方式开始会话",
    "{agent} can't tell those starts apart from its others": "{agent} 无法把这些开始与它的其他开始区分开",
    "Give {agent} all of these hooks": "给 {agent} 启用这些 Hook",
