    "Hook {name}": "Hook {name}",
    "Hooks your agents have that aren't in the library stay as they are, and so does one you changed in an agent's file.": "Agent 自己的、不在资源库中的 Hook 保持不变，你在 Agent 文件里改过的也一样。",
    "Letters, digits, - and _": "字母、数字、- 和 _",
