    "{agents} has no skills folder.": "{agents} 没有技能文件夹。",
    "Claude Desktop shows skill changes once its window is reloaded ({keys}). It gets a copy of each skill, and one you change in Desktop is left as it is.": "Claude Desktop 刷新窗口（{keys}）后才显示技能变化。它使用技能的副本，在 Desktop 中改过的副本不会被覆盖。",
