    "Give a project's agents some of these skills as the project's own: magpie links them into its .claude/skills and .agents/skills and keeps them out of git.": "将部分技能作为项目技能提供给项目中的 Agent：链接到项目的 .claude/skills 和 .agents/skills，并让 git 忽略。",
