    "{skills} are out of {name}": "{skills} 已从 {name} 移除",
    "Placed in {dirs} of the project and kept out of git, its .gitignore untouched. A folder there that isn't magpie's is left as it is.": "放在项目的 {dirs} 中，并让 git 忽略它们，不改 .gitignore。其中非 magpie 放入的文件夹保持不动。",
    "{agents} reads no project skills folder magpie knows of.": "{agents} 没有 magpie 已知的项目技能文件夹。",
    "The skills and MCP servers magpie put in it are taken away. Nothing else in the folder is touched.": "移除 magpie 放入的技能和 MCP 服务器，文件夹中其他内容不受影响。",
    "magpie forgets the project. The skills and MCP servers it put in the folder stay there as they are, kept out of git, and are yours from then on; a linked skill still follows the library's.": "magpie 不再管理此项目。已放入的技能和 MCP 服务器原样保留，仍不进 git，之后由你管理；链接的技能仍跟随资源库版本。",
    "Keep its skills and MCP servers": "保留项目里的技能和 MCP 服务器",
    "Remove the project from magpie only, leaving what magpie wrote into it": "只从 magpie 移除项目，已写入项目的内容保持不动",
    "{name} removed, its skills and servers kept": "已移除 {name}，项目里的技能和服务器已保留",
    "Give a project's agents some of these servers as the project's own: magpie writes them into its {files}, leaving the rest of each file as it is.": "将部分服务器作为项目服务器提供给项目中的 Agent：写入项目的 {files}，文件中其他内容不变。",
    "{name} added — pick the servers it gets": "已添加 {name} — 选择它要用的服务器",
    "No servers yet": "还没有服务器",
    "Hide its servers": "收起服务器",
    "Pick the servers it gets": "选择它要用的服务器",
    "Not written": "未写入",
    "{server} is in {name} for {agents}": "{server} 已写入 {name}，供 {agents} 使用",
    "{server} is out of {name}": "{server} 已从 {name} 移除",
    "Written into {files} of the project, beside what's in them; a file magpie makes is kept out of git, its .gitignore untouched. A server there by the same name that isn't magpie's is left as it is.": "写入项目的 {files}，与已有内容并存；magpie 新建的文件不进 git，不改 .gitignore。其中非 magpie 写入的同名服务器保持不动。",
    "{item} is off in {name} for {agents}": "{item} 已在 {name} 中对 {agents} 关闭",
    "{item} is back on in {name}": "{item} 已在 {name} 中重新开启",
    "{agent} has it from the Library, and can't have it turned off in one project": "{agent} 从资源库获得它，无法只在一个项目中关闭",
    "{agent} reaches {skill} through the skill router, which can't leave it out in one project: set it to not go through the router first": "{agent} 通过技能路由使用 {skill}，技能路由无法只在一个项目中去掉它：先把它设为不经过路由",
    "Claude Code asks before it starts a project's servers; Codex reads .codex/config.toml, and Pi .pi/mcp.json, only in a project you trust.": "Claude Code 启动项目服务器前会先询问；Codex 的 .codex/config.toml 和 Pi 的 .pi/mcp.json 仅在受信任的项目中读取。",
    "{agents} reads no project MCP file magpie knows of.": "{agents} 没有 magpie 已知的项目 MCP 文件。",
    "owner/repo, a GitHub or GitLab link, any git repository's address, or a folder on this computer": "owner/repo、GitHub 或 GitLab 链接、任意 git 仓库地址，或本机上的文件夹",
