    "Up to date with GitHub": "与 GitHub 一致",
    "Changed here": "本地已改动",
    "Manual only": "仅手动",
    "Its SKILL.md sets disable-model-invocation: Claude Code runs it only when you type /{name}, never on its own.": "它的 SKILL.md 设了 disable-model-invocation：只有你输入 /{name} 时 Claude Code 才会运行它，模型不会自己调用。",
    "{name} was removed from its source": "{name} 已从来源中删除",
