    "Clean up {n}": "清理 {n} 个",
    "Remove {name}: its source no longer has it": "移除 {name}：来源里已经没有它了",
    "Remove the {n} skills their source no longer has": "移除来源里已没有的 {n} 个技能",
    "Remove {n} skills removed upstream?": "移除 {n} 个上游已删除的技能？",
    "{repo} no longer has this skill: it was removed there.": "{repo} 里已经没有这个技能了：它在那里被删除了。",
    "{repo} no longer has these skills: they were removed there.": "{repo} 里已经没有这些技能了：它们在那里被删除了。",
    "Their sources no longer have these skills: they were removed there.": "它们的来源里已经没有这些技能了：它们在那里被删除了。",
    "You changed it here since it was fetched.": "获取之后你在本地改过它。",
    "Their folders are moved to magpie's backups (Backups, at the top of the Library), not deleted.": "它们的文件夹会移到 magpie 的备份里（资料库顶部的“备份”），不会被删除。",
    "Removed upstream": "上游已删除",
    "{repo} no longer has this skill: it was removed there. It stays here until you remove it.": "{repo} 里已经没有这个技能了：它在那里被删除了。在你移除之前，它会一直留在这里。",
    "Its source no longer has this skill: it was removed there. It stays here until you remove it.": "来源里已经没有这个技能了：它在那里被删除了。在你移除之前，它会一直留在这里。",
    "You changed it since it was fetched from GitHub. Updating asks before it replaces your changes.": "从 GitHub 获取后你在本地改动过它。更新前会先询问，不会直接覆盖你的改动。",
    "Changed here: asks before it replaces your changes": "本地已改动：更新前会先询问，不会直接覆盖",
    "Replace your changes to {name}?": "用 GitHub 的版本替换你对 {name} 的改动？",
    "You changed {name} here since it was fetched from GitHub. Updating puts GitHub's version in its place. Yours is kept in magpie's backups (Backups, at the top of the Library).": "从 GitHub 获取 {name} 后你在本地改动过它。更新会用 GitHub 的版本替换它，你的版本会保存在 magpie 的备份里（资源库顶部的「备份」）。",
    "Keep mine": "保留我的",
    "{name} is up to date; your version is in the backups": "{name} 已是最新，你的版本已存入备份",
    "{name} is already up to date": "{name} 已是最新",
    "{name} is updated": "{name} 已更新",
    "Kept as you changed them: {names}. Update each from its row to replace your changes.": "已保留你改动过的：{names}。如要用 GitHub 的版本替换，请在各自的行里单独更新。",
    "Update from GitHub ({repo}, as CC Switch installed it)": "从 GitHub 更新（{repo}，CC Switch 安装时的来源）",
    "Read {name}'s SKILL.md": "查看 {name} 的 SKILL.md",
    "Saved in the library: every agent given {name} gets it": "保存在资料库里：每个装了 {name} 的 Agent 都会拿到",
    "It is taken out of every agent it was given to. The folder it was linked from stays where it is.": "将从所有已启用的 Agent 中移除，链接的原文件夹保持不动。",
    "It is taken out of every agent it was given to, and its folder is moved to magpie's backups.": "将从所有已启用的 Agent 中移除，文件夹移到 magpie 的备份。",
    "Its folder is moved to magpie's backups.": "文件夹将移到 magpie 的备份。",
    "It is taken out of {agents}. The folder it was linked from stays where it is.": "将从 {agents} 中移除。它链接到的原文件夹保持不动。",
    "It is taken out of {agents}, and its folder is moved to magpie's backups.": "将从 {agents} 中移除，文件夹移到 magpie 的备份。",
    "Its entry in {path} goes to the backups too, so no agent reads it from there.": "它在 {path} 中的条目也会移到备份，不会再有 Agent 从那里读取。",
    "It is taken out of the MCP settings of {agents}. Each file is copied to magpie's backups before it changes.": "将从 {agents} 的 MCP 配置中移除。每个文件改动前都会先复制到 magpie 的备份。",
    "{agents} has another server by this name; that one stays.": "{agents} 中有另一个同名服务器，那个保持不动。",
    "{agents} has another skill by this name; that one stays.": "{agents} 中有另一个同名 Skill，那个保持不动。",
    "{agents} has another skill by this name; bringing this one in leaves that one as it is": "{agents} 有另一个同名技能；导入这个不会改动那个",
    "Keeps a link to where it is: {agents} go on having it, and you can give it to the others": "保留指向原位置的链接：{agents} 继续拥有它，你也可以给其他 Agent",
    "Moves it into the library and links it back: {agents} go on having it, and you can give it to the others": "移入资源库并链接回去：{agents} 继续拥有它，你也可以给其他 Agent",
    "Keeps it where it is in the shared skills folder and links to it: you can give it to any agent": "保留在共享技能文件夹原处，资源库链接到它：可分配给任何 Agent",
    "Lists it in the library where it is, nothing moved: you can give it to any agent": "在原处列入资源库，不移动文件：可分配给任何 Agent",
    "{agent} reads ~/.agents/skills itself, where this skill is kept — it has it whatever is ticked here": "{agent} 会自行读取此技能所在的 ~/.agents/skills，无论是否勾选都能使用",
    "{agent} still reads {n} of them from ~/.agents/skills itself": "{agent} 仍会自行从 ~/.agents/skills 读取其中 {n} 个",
    "{agent} reads ~/.agents/skills itself, where all of these are kept — it has them whatever is ticked here": "{agent} 会自行读取这些技能所在的 ~/.agents/skills，无论是否勾选都能使用",
    "It reads {n} of them from ~/.agents/skills itself: a click here leaves those as they are": "其中 {n} 个由它自行从 ~/.agents/skills 读取：在这里点击不会改变它们",
    "{n} in ~/.agents/skills": "{n} 个在 ~/.agents/skills",
    "Fold every group": "收起所有分组",
    "Open every group": "展开所有分组",
    "Fold every group that matches the filter": "收起所有符合筛选的分组",
    "Open every group that matches the filter": "展开所有符合筛选的分组",
    "{agents} read ~/.agents/skills themselves: they have these {n} whatever is ticked here, and turning the group off for them leaves those on": "{agents} 会自行读取 ~/.agents/skills：无论这里是否勾选，这 {n} 个技能它们都能使用；为它们关闭此组时，这些仍保持可用",
    "1 result": "1 个结果",
