    "Featured, and the official MCP Registry": "精选，以及官方 MCP Registry",
    "Popular on skills.sh": "skills.sh 热门",
    "skills.sh's search didn't answer ({error}), so these are only the matches among magpie's picks and the most installed skills.": "skills.sh 的搜索这次没有响应（{error}），下面只是 magpie 精选和最热门技能里匹配的结果。",
    "The MCP Registry didn't answer ({error}), so these are only magpie's featured servers that match.": "MCP Registry 这次没有响应（{error}），下面只是 magpie 精选服务器里匹配的结果。",
    "Nothing matches “{q}”.": "没有与“{q}”匹配的结果。",
