    "＋ Add it yourself…": "＋ 自己添加…",
    "Nothing to show.": "暂无内容。",
    "Remote · sign-in": "远程 · 需登录",
    "In the library as {name}": "已在资源库中，名为 {name}",
    "adds as {name}": "将添加为 {name}",
    "links to GitHub": "链接到 GitHub",
    "The library's {name} came from a folder. This one takes its place and it updates from GitHub from then on; files of its own that differ are kept with the backups.": "资源库里的 {name} 来自一个文件夹。这个会取代它，之后它从 GitHub 更新；与此不同的原有文件会保留在备份里。",
    "The library has another skill called {name}, from elsewhere. This one goes in beside it as {as}.": "资源库里已有一个来自别处、同样叫 {name} 的技能。这一个会以 {as} 为名，和它并存。",
    "Needs {what} to add": "添加时需要 {what}",
    "Add…": "添加…",
    "About {name}": "关于 {name}",
    "Each agent asks you to sign in, in the browser, the first time it uses it.": "每个 Agent 首次使用时会在浏览器中请你登录。",
