    "Learn from conversations": "從對話中學習",
    "Reads each finished conversation for what to remember. You review each one before agents see it.": "讀完成的對話，找出值得記住的內容。每條都要你確認後 Agent 才會看到。",
    "Reading conversations…": "正在讀對話…",
