    "Reads conversations quiet for 30 minutes, every hour": "每小時讀一次已停止 30 分鐘的對話",
    "Read now": "立即讀取",
    "Tidy up every night": "每晚整理",
    "Merges memories that repeat and sets aside ones out of date. What you wrote or pinned stays.": "合併重複的記憶，封存過時的記憶。你寫的和釘選的保持不變。",
