    "Search by meaning": "依意思搜尋",
    "Finds memories that mean what you search for, in any language. Downloads a {size} model that runs on this computer.": "依意思找到相關的記憶，不限語言。會下載一個 {size} 的模型，在這台電腦上執行。",
    "Downloading the model · {p}%": "正在下載模型 · {p}%",
