    "Couldn't read the memories: {error}": "無法讀取記憶：{error}",
    "Reading the memories · {n} of {m}": "正在讀取記憶 · {n}/{m}",
    "Finds memories that mean what you search for, in any language, on this computer.": "依意思找到相關的記憶，不限語言，在這台電腦上執行。",
    "Tidied {when} · undone": "{when}整理過 · 已復原",
