    "Nothing to tidy {when}": "{when}沒有需要整理的",
    "Tidy now": "立即整理",
    "What your agents know about you and your projects, shared by all of them. They search it and save to it with Magpie Memory, and the agents switched on under Instructions read a summary of it.": "Agent 們對你和你的專案的了解，所有 Agent 共用。它們透過 Magpie Memory 搜尋和儲存記憶；在「指令」中開啟的 Agent 還會讀到記憶摘要。",
    "In the agents' instructions": "寫入 Agent 的指令",
    "No agent is switched on under Instructions": "「指令」中沒有開啟任何 Agent",
    "The agents read the memories' summary": "Agent 現在會讀到記憶摘要",
    "The memories' summary is taken out of the agents' instructions": "已從 Agent 的指令中移除記憶摘要",
    "Add it for agents to search and save memories": "新增後，Agent 才能搜尋和儲存記憶",
    "Search memories": "搜尋記憶",
