    "Can't start it": "無法啟動",
    "exited ({code})": "已退出（{code}）",
    "It exited with code {code} before listing its tools": "列出工具前就退出了，退出碼 {code}",
    "It started in a project folder and listed its tools, as an agent starts it there. It exits when started in your home folder": "在專案資料夾裡啟動並列出了它的工具，和 Agent 在專案裡啟動它時一樣。在你的主資料夾裡啟動時它會退出",
    "won't start in home": "在主資料夾裡無法啟動",
    "It exits when started in your home folder, where magpie runs it for the agents given it, and works in a project folder. Turn off Through the MCP router in its editor, so each agent starts it in its own project": "在你的主資料夾裡啟動時它會退出，而 magpie 正是在那裡為分配到它的 Agent 執行它；在專案資料夾裡則正常。在它的編輯頁關掉「經過 MCP 路由」，讓每個 Agent 在自己的專案裡啟動它",
    "It exited before listing its tools": "列出工具前就退出了",
    "No answer in {n} seconds": "{n} 秒內沒有回應",
    "no answer to {step}": "{step} 無回應",
    "No answer to {step} in {n} seconds": "等了 {n} 秒，{step} 仍沒有回應",
