    "Copy config…": "複製設定…",
    "As Claude Code's .mcp.json has it. A value naming a variable, as {ref}, stays a name here": "與 Claude Code 的 .mcp.json 格式相同。像 {ref} 這樣引用變數的值，在這裡仍然是變數名稱",
