    "Before a tool runs": "工具執行之前",
    "Codex runs a new or changed hook only once you trust it: review it in Codex's /hooks.": "新增或改過的 Hook，Codex 要等你信任後才會執行：請在 Codex 的 /hooks 裡審閱。",
    "Cursor runs Claude Code's hooks too: a hook given to both runs twice in Cursor.": "Cursor 也會執行 Claude Code 的 Hook：同時給兩者啟用的 Hook，在 Cursor 裡會執行兩次。",
