    "{skills} are out of {name}": "{skills} 已從 {name} 移除",
    "Placed in {dirs} of the project and kept out of git, its .gitignore untouched. A folder there that isn't magpie's is left as it is.": "放在專案的 {dirs} 中，並讓 git 忽略它們，不改 .gitignore。其中非 magpie 放入的資料夾保持不動。",
    "{agents} reads no project skills folder magpie knows of.": "{agents} 沒有 magpie 已知的專案技能資料夾。",
    "The skills and MCP servers magpie put in it are taken away. Nothing else in the folder is touched.": "移除 magpie 放入的技能和 MCP 伺服器，資料夾中其他內容不受影響。",
    "magpie forgets the project. The skills and MCP servers it put in the folder stay there as they are, kept out of git, and are yours from then on; a linked skill still follows the library's.": "magpie 不再管理此專案。已放入的技能和 MCP 伺服器原樣保留，仍不進 git，之後由你管理；連結的技能仍跟隨資源庫版本。",
    "Keep its skills and MCP servers": "保留專案裡的技能和 MCP 伺服器",
    "Remove the project from magpie only, leaving what magpie wrote into it": "只從 magpie 移除專案，已寫入專案的內容保持不動",
    "{name} removed, its skills and servers kept": "已移除 {name}，專案裡的技能和伺服器已保留",
    "Give a project's agents some of these servers as the project's own: magpie writes them into its {files}, leaving the rest of each file as it is.": "將部分伺服器作為專案伺服器提供給專案中的 Agent：寫入專案的 {files}，檔案中其他內容不變。",
