    "{agents} reads no project MCP file magpie knows of.": "{agents} 沒有 magpie 已知的專案 MCP 檔案。",
    "owner/repo, a GitHub or GitLab link, any git repository's address, or a folder on this computer": "owner/repo、GitHub 或 GitLab 連結、任何 git 儲存庫位址，或本機上的資料夾",
