    "{repo} no longer has this skill: it was removed there. It stays here until you remove it.": "{repo} 裡已經沒有這個技能了：它在那裡被刪除了。在你移除之前，它會一直留在這裡。",
    "Its source no longer has this skill: it was removed there. It stays here until you remove it.": "來源裡已經沒有這個技能了：它在那裡被刪除了。在你移除之前，它會一直留在這裡。",
    "You changed it since it was fetched from GitHub. Updating asks before it replaces your changes.": "從 GitHub 取得後你在本機改動過它。更新前會先詢問，不會直接覆蓋你的改動。",
