    "Replace your changes to {name}?": "用 GitHub 的版本取代你對 {name} 的改動？",
    "You changed {name} here since it was fetched from GitHub. Updating puts GitHub's version in its place. Yours is kept in magpie's backups (Backups, at the top of the Library).": "從 GitHub 取得 {name} 後你在本機改動過它。更新會用 GitHub 的版本取代它，你的版本會保存在 magpie 的備份裡（資源庫頂部的「備份」）。",
