    "Read {name}'s SKILL.md": "檢視 {name} 的 SKILL.md",
    "Saved in the library: every agent given {name} gets it": "儲存在資料庫裡：每個裝了 {name} 的 Agent 都會拿到",
    "It is taken out of every agent it was given to. The folder it was linked from stays where it is.": "將從所有已啟用的 Agent 中移除，連結的原資料夾保持不動。",
    "It is taken out of every agent it was given to, and its folder is moved to magpie's backups.": "將從所有已啟用的 Agent 中移除，資料夾移到 magpie 的備份。",
    "Its folder is moved to magpie's backups.": "資料夾將移到 magpie 的備份。",
    "It is taken out of {agents}. The folder it was linked from stays where it is.": "將從 {agents} 中移除。它連結到的原資料夾保持不動。",
    "It is taken out of {agents}, and its folder is moved to magpie's backups.": "將從 {agents} 中移除，資料夾移到 magpie 的備份。",
    "Its entry in {path} goes to the backups too, so no agent reads it from there.": "它在 {path} 中的項目也會移到備份，不會再有 Agent 從那裡讀取。",
    "It is taken out of the MCP settings of {agents}. Each file is copied to magpie's backups before it changes.": "將從 {agents} 的 MCP 設定中移除。每個檔案改動前都會先複製到 magpie 的備份。",
