    "{agents} has another skill by this name; bringing this one in leaves that one as it is": "{agents} 有另一個同名技能；匯入這個不會改動那個",
    "Keeps a link to where it is: {agents} go on having it, and you can give it to the others": "保留指向原位置的連結：{agents} 繼續擁有它，你也可以給其他 Agent",
    "Moves it into the library and links it back: {agents} go on having it, and you can give it to the others": "移入資源庫並連結回去：{agents} 繼續擁有它，你也可以給其他 Agent",
    "Keeps it where it is in the shared skills folder and links to it: you can give it to any agent": "保留在共享技能資料夾原處，資源庫連結到它：可分配給任何 Agent",
    "Lists it in the library where it is, nothing moved: you can give it to any agent": "在原處列入資源庫，不移動檔案：可分配給任何 Agent",
    "{agent} reads ~/.agents/skills itself, where this skill is kept — it has it whatever is ticked here": "{agent} 會自行讀取此技能所在的 ~/.agents/skills，無論是否勾選都能使用",
    "{agent} still reads {n} of them from ~/.agents/skills itself": "{agent} 仍會自行從 ~/.agents/skills 讀取其中 {n} 個",
