    "WSL {distro} isn't running, and magpie hasn't seen {agent}'s files there yet: start the distro to change this": "WSL {distro} 未執行，magpie 還沒見過 {agent} 在那裡的檔案：啟動該發行版後才能修改",
    "WSL {distro} isn't running: {agent} has it — click to take it away, and magpie writes the change there the next time it runs": "WSL {distro} 未執行：{agent} 已啟用——點一下移除，magpie 會在它下次執行時寫入",
