    "The file has instructions besides magpie's part — they stay, and the agent reads both": "ファイルには magpie の部分以外にも指示があります — それらは残り、エージェントは両方を読み込みます",
    "{agent} reads the shared instructions": "{agent} は共有指示を読み込みます",
    "Taken out of {agent}'s file": "{agent} のファイルから削除しました",
