    "{agent} reads {file} instead of this file while it has anything in it.": "{agent} は {file} に内容がある間、このファイルの代わりにそれを読み込みます。",
    "{agent} reads Claude Code's CLAUDE.md when it has no AGENTS.md of its own.": "{agent} は独自の AGENTS.md がないとき、Claude Code の CLAUDE.md を読み込みます。",
    "This file is {agent}'s profile of you: magpie adds its part after yours and leaves your own lines in it. A USER.md in a workspace is read instead of this one.": "このファイルは {agent} にとってのあなたのプロフィールです。magpie は自分の部分をあなたの内容の後に追加し、あなた自身の行はそのまま残します。ワークスペースに USER.md があると、こちらの代わりにそれが読み込まれます。",
    "Antigravity reads Gemini CLI's ~/.gemini/GEMINI.md as well as this file, so text given to both is read twice.": "Antigravity はこのファイルに加えて Gemini CLI の ~/.gemini/GEMINI.md も読み込むため、両方に書いた内容は 2 回読まれます。",
    "Only for {agent}, after the shared text": "{agent} 専用、共有テキストの後に追加",
    "Anything only {agent} should be told": "{agent} だけに伝える内容",
    "Switch {agent} on for it to read this.": "{agent} をオンにすると、これを読むようになります。",
    "Move its own into the shared text": "固有の内容を共有テキストに移す",
    "Moved into the shared instructions — {agent} reads the same as before": "共有指示に移しました — {agent} が読む内容は以前と同じです",
    "Takes the {n} lines out of the file, adds them to the shared text, and switches {agent} on — so it reads what it read before, and the other agents can too": "ファイルから {n} 行を取り出して共有テキストに追加し、{agent} をオンにします — 以前と同じ内容を読み、他のエージェントも読めるようになります",
    "Write the library's text again": "ライブラリのテキストを再度書き込む",
    "{agent}'s file has the library's text again": "{agent} のファイルをライブラリのテキストに戻しました",
    "Replaces what was changed in magpie's part of the file; the file is kept aside first": "ファイル内の magpie の部分で変更された箇所を置き換えます。先にファイルをバックアップします",
    "{agent} can't reach a server over SSE — only a command or streamable HTTP": "{agent} は SSE 経由のサーバーに接続できません — コマンドまたは streamable HTTP のみ対応しています",
    "{agent} can't read {ref} from its settings — given this server, the token would be written there as plain text": "{agent} は設定から {ref} を読み取れません — このサーバーを渡すと、トークンが平文で設定に書き込まれます",
    "A value can name a variable, as {ref}: each agent is given it in its own way, so the token stays out of its settings": "値には {ref} の形で環境変数を指定できます。各エージェントにはそれぞれの書式で渡されるため、トークンは設定に書き込まれません",
