    "{skills} are out of {name}": "{skills} sind aus {name} entfernt",
    "Placed in {dirs} of the project and kept out of git, its .gitignore untouched. A folder there that isn't magpie's is left as it is.": "In {dirs} des Projekts abgelegt und aus git herausgehalten, ohne seine .gitignore anzurühren. Ein Ordner dort, der nicht von magpie stammt, bleibt unverändert.",
    "{agents} reads no project skills folder magpie knows of.": "{agents} liest keinen Projekt-Skills-Ordner, den magpie kennt.",
    "The skills and MCP servers magpie put in it are taken away. Nothing else in the folder is touched.": "Die Skills und MCP-Server, die magpie dort abgelegt hat, werden entfernt. Sonst wird im Ordner nichts angerührt.",
    "magpie forgets the project. The skills and MCP servers it put in the folder stay there as they are, kept out of git, and are yours from then on; a linked skill still follows the library's.": "magpie vergisst das Projekt. Die Skills und MCP-Server, die es im Ordner abgelegt hat, bleiben unverändert dort, weiter aus git herausgehalten, und gehören ab dann Ihnen; ein verlinkter Skill folgt weiterhin dem der Bibliothek.",
    "Keep its skills and MCP servers": "Skills und MCP-Server behalten",
