    "{name} removed, its skills and servers kept": "{name} entfernt, Skills und Server behalten",
    "Give a project's agents some of these servers as the project's own: magpie writes them into its {files}, leaving the rest of each file as it is.": "Geben Sie den Agenten eines Projekts einige dieser Server als projekteigene: magpie schreibt sie in dessen {files} und lässt den Rest jeder Datei unverändert.",
