    "{agent} reaches {skill} through the skill router, which can't leave it out in one project: set it to not go through the router first": "{agent} erreicht {skill} über den Skill-Router, der es nicht nur in einem Projekt weglassen kann: stellen Sie es zuerst so ein, dass es nicht über den Router geht",
